import{_ as t,o as e,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-13（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-13.md","filePath":"topics/biomedicine/science-daily-2026-10-13.md"}'),i={name:"topics/biomedicine/science-daily-2026-10-13.md"};function r(c,o,a,d,l,g){return e(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-13-生物医学" tabindex="-1">科学日报 · 2026-10-13（生物医学） <a class="header-anchor" href="#科学日报-·-2026-10-13-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-10-13（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> — 第36期 ｜ 科学板块</p></blockquote><hr><h2 id="细菌用-端粒酶式-逆转录来抗病毒-nature" tabindex="-1">细菌用&quot;端粒酶式&quot;逆转录来抗病毒（Nature） <a class="header-anchor" href="#细菌用-端粒酶式-逆转录来抗病毒-nature" aria-label="Permalink to &quot;细菌用&quot;端粒酶式&quot;逆转录来抗病毒（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ DOI: 10.1038/s41586-026-11250-8</p></blockquote><ul><li>对象：细菌的<strong>防御相关逆转录酶（DRT, defense-associated reverse transcriptase）<strong>家族——已知用多种 cDNA 合成机制抗病毒，但</strong>多数成员的功能/机制未知</strong>。</li><li>新系统：鉴别出 <strong>DRT10</strong>，它与一段<strong>非编码 RNA（ncRNA）<strong>结合，催化</strong>持续性的、蛋白引物（protein-primed）<strong>的</strong>串联重复 DNA</strong> 合成。</li><li>模板机制：逆转录以 ncRNA 上一段带<strong>特征序列模式 + 模板边界元件</strong>的区域为模板——两者都<strong>保守且对 DNA 重复添加必需</strong>。</li><li>结构：冷冻电镜揭示<strong>罕见的 2:1 结构</strong>——<strong>两个 RT 单体</strong>结合在一条<strong>拟对称 ncRNA</strong> 的两侧；每个单体各自逆转录自己一侧的模板，但<strong>只有一侧产生长重复产物</strong>，其模板由<strong>两个侧翼发夹锚点之间的间距</strong>定义。</li><li>演化：这种<strong>迭代、边界受限</strong>的 cDNA 合成与<strong>真核端粒酶加端粒重复</strong>直接平行；跨生命域的 RT 系统发生分析把<strong>端粒酶与 DRT 家族放进同一单系支</strong>，提示二者 DNA 聚合活动有<strong>共同起源</strong>。</li><li>洞察（对本库 <code>biomedicine</code> / <code>physics</code>）：<strong>&quot;边界&quot;是重复合成的关键旋钮</strong>——端粒酶与细菌防御系统都用&quot;<strong>两个锚点之间的固定距离</strong>&quot;决定复制单元长度。细菌↔真核在<strong>同一分子逻辑</strong>上撞车，是&quot;进化复用&quot;的典型：<strong>抗病毒免疫与染色体维护共用了同一套逆转录工具箱</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第36期 科学板块</p></blockquote><p>关键词：防御相关逆转录酶、DRT、DRT10、非编码 RNA、ncRNA、蛋白引物、串联重复 DNA、模板边界元件、拟对称 ncRNA、2:1 结构、冷冻电镜、发夹锚点、端粒酶、端粒重复加尾、单系演化、共同起源、细菌抗病毒免疫 关联：<code>topics/biomedicine/science-daily-2026-10-12.md</code>（转录/调控层面：21 三体发育扰动；肠道菌—代谢物轴）、<code>topics/biomedicine/chloroplast-endosymbiosis.md</code>（内共生/进化复用母题）、<code>topics/quantum-physics/science-daily-2026-10-13.md</code>（同日：把&quot;拓扑/边界&quot;作为信息载体）</p>',9)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
